  COALESCE(                (SELECT value FROM m_payment_type WHERE id = a.payment_type_id),                a.classification_name        ) AS PaymentType_Name,     a.chargetype AS chargetype,     a.reversal_indicator AS Reversed,     a.Allocation_Type AS Allocation_Type,     (SELECT code_value FROM m_code_value WHERE id = a.charge_off_reason_id) AS Chargeoff_ReasonCode,     CASE         WHEN a.transaction_type = 9999 THEN sum(a.amount) * + 1         WHEN a.transaction_type = 99999 THEN sum(a.amount) * - 1         WHEN a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 28, 31, 33, 34, 37, 39)         AND a.reversal_indicator = false THEN sum(a.amount) * -1         WHEN a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 28, 31, 33, 34, 37, 39)         AND a.reversal_indicator = true THEN sum(a.amount) * + 1         WHEN a.transaction_type IN (1, 10, 25, 20, 35, 36)         AND a.reversal_indicator = false THEN sum(a.amount) * + 1         WHEN a.transaction_type IN (1, 10, 25, 20, 35, 36)         AND a.reversal_indicator = true THEN sum(a.amount) * -1     END AS Transaction_Amount,     (SELECT external_id FROM m_external_asset_owner WHERE id = a.asset_owner_id) AS Asset_owner_id,     (SELECT external_id FROM m_external_asset_owner WHERE id = a.from_asset_owner_id) AS From_asset_owner_id FROM (         SELECT t.transactiondate,             t.id,             t.name AS product,             t.transaction_type_enum AS transaction_type,             t.payment_type_id,             t.classification_name,             '' AS chargetype,             false AS reversal_indicator,             'Principal' AS Allocation_Type,             CASE                 WHEN t.transaction_type_enum in (1) THEN (                     CASE                         WHEN t.amount is null THEN 0                         WHEN t.overpayment_portion_derived is null THEN t.amount                         WHEN t.overpayment_portion_derived is not null THEN t.amount - t.overpayment_portion_derived                         ELSE t.amount                     END                 )                 ELSE (                     CASE                         WHEN t.principal_portion_derived is null THEN 0                         ELSE t.principal_portion_derived                     end                 )             END amount,             CASE                 WHEN t.status in ('ACTIVE', 'ACTIVE_INTERMEDIATE')                 AND t.settlement_date < '${endDate}' THEN t.owner_id             END AS asset_owner_id,             CASE                 WHEN t.transaction_type_enum = 27                 OR (t.charged_off_on_date <= t.transaction_date) THEN t.charge_off_reason_cv_id             END AS charge_off_reason_id,             null::bigint AS from_asset_owner_id         FROM slt_except_charge_adj_and_accrual AS t          UNION ALL          SELECT t.transactiondate,             t.id,             t.name AS product,             t.transaction_type_enum AS transaction_type,             t.payment_type_id,             t.classification_name,             '' AS chargetype,             false AS reversal_indicator,             'Interest' AS Allocation_Type,             CASE                 WHEN t.interest_portion_derived is null THEN 0                 ELSE t.interest_portion_derived             END AS amount,             CASE                 WHEN t.status in ('ACTIVE', 'ACTIVE_INTERMEDIATE')                 AND t.settlement_date < '${endDate}' THEN t.owner_id             END AS asset_owner_id,             CASE                 WHEN t.transaction_type_enum = 27                 OR (t.charged_off_on_date <= t.transaction_date) THEN t.charge_off_reason_cv_id             END AS charge_off_reason_id,             null::bigint AS from_asset_owner_id         FROM slt_except_charge_adj_and_accrual AS t          UNION ALL          SELECT t.transactiondate,             t.id,             t.name AS product,             t.transaction_type_enum AS transaction_type,             t.payment_type