_derived,         t.penalty_charges_portion_derived,         t.amount,         e.status,         e.settlement_date,         e.owner_id,         m.charged_off_on_date,         t.transaction_date,         m.charge_off_reason_cv_id     FROM m_loan_transaction t         JOIN m_loan m ON m.id = t.loan_id         JOIN m_product_loan l ON l.id = m.product_id         LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id         LEFT JOIN m_external_asset_owner_transfer e ON e.loan_id = t.loan_id         AND e.settlement_date < '${endDate}'         AND e.effective_date_to >= '${endDate}'     WHERE t.reversed_on_date = '${endDate}'         AND t.transaction_type_enum = 26         AND (t.office_id = ${officeId})  ),  slt_cap_income_amortization AS (     SELECT '${endDate}' AS transactiondate,         t.id,         l.name,         t.transaction_type_enum,         d.payment_type_id,         CASE             WHEN d.payment_type_id IS NULL AND bt.classification_cv_id IS NOT NULL                 THEN                     (SELECT code_value FROM m_code_value WHERE id = bt.classification_cv_id)             ELSE NULL             END AS classification_name,         t.overpayment_portion_derived,         t.principal_portion_derived,         t.interest_portion_derived,         t.fee_charges_portion_derived,         t.penalty_charges_portion_derived,         t.amount,         e.status,         e.settlement_date,         e.owner_id,         m.charged_off_on_date,         t.transaction_date,         m.charge_off_reason_cv_id     FROM m_loan_transaction t         JOIN m_loan m ON m.id = t.loan_id         JOIN m_product_loan l ON l.id = m.product_id         LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id         JOIN m_loan_amortization_allocation_mapping map             ON map.amortization_loan_transaction_id = t.id         JOIN m_loan_transaction bt ON bt.id = map.base_loan_transaction_id             LEFT JOIN m_external_asset_owner_transfer e                 ON e.loan_id = t.loan_id                 AND e.settlement_date < '${endDate}'                 AND e.effective_date_to >= '${endDate}'     WHERE t.submitted_on_date = '${endDate}'         AND t.is_reversed = false         AND t.transaction_type_enum IN (36, 39)         AND (t.office_id = ${officeId}) ), rlt_cap_income_amortization AS (     SELECT '${endDate}' AS transactiondate,         t.id,         l.name,         t.transaction_type_enum,         d.payment_type_id,         CASE             WHEN d.payment_type_id IS NULL AND bt.classification_cv_id IS NOT NULL                 THEN                     (SELECT code_value FROM m_code_value WHERE id = bt.classification_cv_id)             ELSE NULL             END AS classification_name,         t.overpayment_portion_derived,         t.principal_portion_derived,         t.interest_portion_derived,         t.fee_charges_portion_derived,         t.penalty_charges_portion_derived,         t.amount,         e.status,         e.settlement_date,         e.owner_id,         m.charged_off_on_date,         t.transaction_date,         m.charge_off_reason_cv_id     FROM m_loan_transaction t         JOIN m_loan m ON m.id = t.loan_id         JOIN m_product_loan l ON l.id = m.product_id         LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id         JOIN m_loan_amortization_allocation_mapping map             ON map.amortization_loan_transaction_id = t.id         JOIN m_loan_transaction bt ON bt.id = map.base_loan_transaction_id             LEFT JOIN m_external_asset_owner_transfer e             ON e.loan_id = t.loan_id             AND e.settlement_date < '${endDate}'             AND e.effective_date_to >= '${endDate}'     WHERE         t.reversed_on_date = '${endDate}'         AND t.is_reversed = true         AND t.transaction_type_enum IN (36, 39)         AND (t.office_id = ${officeId}) ), active_external_asset_owner_transfers AS (     SELECT '${endDate}' AS transactiondate,         t.id,         p.name,         t.owner_id,         dt.pri